(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const mode=document.body.dataset.candidate;
const names={archives:'档案',schema:'类型与表单',versioning:'版本管理',browser:'浏览器'};
const state={page:'archives',scenario:'default',tab:'资料',title:'青禾计划',draft:'',saved:false,relation:false,typeCreated:false,form:'项目概览',history:false,space:'task',control:'agent',imported:false,restored:false,layout:'side',migration:0,query:'',message:'',typeName:'研究主题',fieldLabel:'项目名称',policy:{interval:5,days:30,quota:1},taking:false};
const commonFields=()=>[{id:'created',label:'创建时间',display:true,system:true},{id:'updated',label:'更新时间',display:true,system:true}];
state.catalog=[{id:'project',label:'项目',fields:[{id:'code',label:'项目编号',display:true},{id:'stage',label:'阶段',display:true},{id:'owner',label:'负责人',display:false},...commonFields()]},{id:'person',label:'个人',fields:[{id:'company',label:'所属企业',display:true},{id:'phone',label:'电话',display:false},...commonFields()]},{id:'company',label:'企业',fields:[{id:'region',label:'地区',display:true},{id:'contact',label:'联系人',display:false},...commonFields()]},{id:'research',label:'研究主题',fields:[{id:'topic',label:'主题方向',display:true},...commonFields()]},{id:'tax',label:'税务事项',fields:[{id:'period',label:'所属期间',display:true},...commonFields()]}];
const seed=(id,type,name,values={})=>({id,type,name,values,body:'整理'+name+'的资料，保留原始记录和关联信息。',created:'2026-10-20 09:00',updated:'2026-10-26 14:32'});
state.records=[seed('p1','project','青禾计划',{code:'QH-001',stage:'进行中',owner:'林夏'}),seed('p2','project','秋季资料整理',{code:'QH-002',stage:'草稿',owner:'陈舟'}),seed('p3','project','山海访谈归档',{code:'QH-003',stage:'已完成',owner:'林夏'}),seed('u1','person','林夏',{company:'山海工作室',phone:'示例号码'}),seed('u2','person','陈舟',{company:'山海工作室',phone:'未填写'}),seed('c1','company','山海工作室',{region:'台北',contact:'林夏'}),seed('r1','research','本地资料的长期保存',{topic:'知识管理'})];
state.activeType='project';state.archiveView=document.body.dataset.start==='detail'?'detail':'list';state.recordId=state.archiveView==='detail'?'p1':null;state.expanded=new Set(['project','person','company']);state.treeQuery='';state.listPrefs={};
function activeType(){return state.catalog.find(t=>t.id===state.activeType)||state.catalog[0];}
function typeTitle(t=activeType()){return t.label.endsWith('档案')?t.label:t.label+'档案';}
function listPrefs(){return state.listPrefs[state.activeType]??=( {layout:'list',query:'',sort:'updated',filter:''} );}
function fieldValue(r,id){return id==='created'?r.created:id==='updated'?r.updated:(r.values[id]??'—');}
function tree(){const q=state.treeQuery.trim();return `<ul class="archive-tree" role="tree" aria-label="档案类型与实例">${state.catalog.map(t=>{const all=state.records.filter(r=>r.type===t.id).sort((a,b)=>a.name.localeCompare(b.name,'zh')),matches=all.filter(r=>!q||t.label.includes(q)||r.name.includes(q));if(q&&!t.label.includes(q)&&!matches.length)return'';const open=q?true:state.expanded.has(t.id);const selected=state.activeType===t.id&&state.archiveView==='list';return `<li role="treeitem" tabindex="${selected?'0':'-1'}" aria-label="${esc(t.label)}" aria-level="1" aria-expanded="${open}" aria-selected="${selected}" data-type-row="${t.id}"><div class="tree-line"><button class="tree-chevron" data-toggle-type="${t.id}" aria-label="${open?'折叠':'展开'}${esc(t.label)}" tabindex="-1">${open?'⌄':'›'}</button><span class="tree-folder" aria-hidden="true">▱</span><span class="tree-name">${esc(t.label)}</span><small>${all.length}</small></div>${open?`<ul role="group">${matches.map(r=>`<li role="treeitem" aria-level="2" aria-label="${esc(r.name)}" aria-selected="${state.recordId===r.id&&state.archiveView==='detail'}" tabindex="${state.recordId===r.id&&state.archiveView==='detail'?'0':'-1'}" data-record-row="${r.id}"><div class="tree-line tree-leaf"><span class="tree-file" aria-hidden="true">▫</span><span class="tree-name">${esc(r.name)}</span></div></li>`).join('')}${!matches.length?'<li role="none" class="tree-empty">暂无档案</li>':''}</ul>`:''}</li>`;}).join('')}</ul>`;}
function archiveList(){const type=activeType(),prefs=listPrefs(),all=state.records.filter(r=>r.type===type.id),fields=type.fields.filter(f=>f.display);let records=all.filter(r=>(!prefs.query||r.name.includes(prefs.query)||fields.some(f=>String(fieldValue(r,f.id)).includes(prefs.query)))&&(!prefs.filter||r.values.stage===prefs.filter));records.sort((a,b)=>prefs.sort==='name'?a.name.localeCompare(b.name,'zh'):String(fieldValue(b,prefs.sort)).localeCompare(String(fieldValue(a,prefs.sort))));
const title=heading(typeTitle(type),`共 ${all.length} 份档案`,button('类型设置','display-fields')+button('新建档案','create','primary'),'档案');
const toolbar=`<div class="archive-toolbar"><label class="archive-search"><span class="sr-only">搜索当前类型档案</span><input id="record-search" type="search" placeholder="搜索${esc(type.label)}档案…" value="${esc(prefs.query)}"></label><div class="view-switch" role="group" aria-label="实例显示方式"><button data-list-layout="list" aria-pressed="${prefs.layout==='list'}">列表</button><button data-list-layout="card" aria-pressed="${prefs.layout==='card'}">卡片</button></div>${button('筛选','record-filter')}<label><span class="sr-only">档案排序</span><select id="record-sort"><option value="updated" ${prefs.sort==='updated'?'selected':''}>按更新时间</option><option value="created" ${prefs.sort==='created'?'selected':''}>按创建时间</option><option value="name" ${prefs.sort==='name'?'selected':''}>按名称</option></select></label></div>`;
const emptyState=state.scenario==='empty'||!all.length;const noResults=state.scenario==='noresults'||!records.length;
const content=emptyState?`<section class="empty"><h2>还没有${esc(type.label)}档案</h2><p class="muted">从第一份${esc(type.label)}档案开始。</p><div class="actions">${button('新建档案','create','primary')}</div></section>`:noResults?`<section class="empty"><h2>没有匹配的档案</h2><p class="muted">已有档案仍保留，试着调整搜索或筛选条件。</p><div class="actions">${button('清除搜索与筛选','clear-list')}</div></section>`:prefs.layout==='card'?`<section class="archive-cards" aria-label="${esc(type.label)}档案卡片">${records.map(r=>`<button class="archive-card" data-record-open="${r.id}"><span class="card-title"><span class="avatar">${esc(r.name[0])}</span><strong>${esc(r.name)}</strong></span><dl>${fields.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(fieldValue(r,f.id))}</dd></div>`).join('')}</dl></button>`).join('')}</section>`:`<div class="archive-table table-wrap" tabindex="0" role="region" aria-label="${esc(type.label)}档案列表，可横向滚动"><table><thead><tr><th>档案名称</th>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}</tr></thead><tbody>${records.map(r=>`<tr data-list-record="${r.id}"><td><button class="record-title ghost" data-record-open="${r.id}">${esc(r.name)}</button></td>${fields.map(f=>`<td data-field="${f.id}">${esc(fieldValue(r,f.id))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
return title+notice()+toolbar+(prefs.filter?`<div class="actions filter-summary"><span class="pill">阶段：${esc(prefs.filter)}</span>${button('清除筛选','clear-list','ghost')}</div>`:'')+`<section id="archive-results">${content}</section><p class="subtitle">显示字段来自「${esc(type.label)}」类型设置。创建时间、更新时间默认显示。</p>`;}
function rememberRecord(){if(state.archiveView!=='detail')return;const r=state.records.find(r=>r.id===state.recordId);if(!r)return;const name=$('#title-input'),body=$('#body-note');if(name)r.name=name.value;if(body)r.body=body.value;$$('[data-value-field]').filter(x=>!x.readOnly).forEach(x=>{r.values[x.dataset.valueField]=x.value;});}
function chooseType(id){rememberRecord();state.activeType=id;state.archiveView='list';state.recordId=null;state.expanded.add(id);state.page='archives';state.scenario='default';state.tab='资料';if($('#drawer').open)$('#drawer').close();render(true);}
function chooseRecord(id){rememberRecord();const r=state.records.find(r=>r.id===id);if(!r)return;state.recordId=id;state.activeType=r.type;state.archiveView='detail';state.expanded.add(r.type);state.title=r.name;state.draft=r.body;state.page='archives';state.scenario='default';state.tab='资料';state.saved=false;if($('#drawer').open)$('#drawer').close();render(true);}
const labels={default:'正常',empty:'空数据',loading:'加载中',error:'读取失败',permission:'只读权限',conflict:'原生笔记未保存',recovery:'恢复中断',unknown:'结果待核实',quota:'历史配额不足',unsupported:'平台不支持',noresults:'搜索无结果'};
let trigger=null,timer=null;
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const action=(text,page)=>`<button class="navrow" data-page="${page}"><span>${text}</span><span aria-hidden="true">↗</span></button>`;
function say(text){$('#announcer').textContent=text;}
function heading(title,sub,buttons='',eyebrow=''){return `<div class="heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${esc(title)}</h1><p class="subtitle">${sub}</p></div><div class="actions">${buttons}</div></div>`;}
function nav(){let body='';if(state.page==='browser'){body=`<div class="side-label">空间</div><button class="navrow ${state.space==='task'?'active':''}" data-action="task"><span>青禾资料调研<small>任务空间 · 2 个标签页</small></span></button><button class="navrow ${state.space==='personal'?'active':''}" data-action="personal"><span>个人浏览<small>仅自己使用</small></span></button><div class="side-label">资源</div>${button('身份与 Cookie','identity','navrow')}${button('文件与材料','files','navrow')}<div class="side-note">空间各自保存登录状态。关闭智能体不影响浏览器。</div>`;}else if(state.page==='versioning'){body=`<div class="side-label">仓库</div>${['更改','历史','比较'].map(t=>`<button class="navrow ${state.tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}<div class="side-label">笔记历史</div><button class="navrow active" data-action="note"><span>调研摘要.md<small>今天 14:32 · 已选中</small></span></button><button class="navrow" data-action="archive-history"><span>青禾计划.md<small>受管档案 · 仅安全恢复</small></span></button>${button('自动历史设置','settings','navrow')}<div class="side-note">历史来源分开显示：Git 提交、本地历史与当前未保存内容。</div>`;}else{body=`<label class="sr-only" for="search">搜索档案类型与实例</label><input id="search" placeholder="搜索类型或档案…" value="${esc(state.treeQuery)}"><div id="archive-tree-host">${tree()}</div><div class="archive-tree-footer">${action('管理档案类型','schema')}</div>`;}
$('#sidebar').innerHTML=`<header>${names[state.page]} <span class="muted">⌄</span></header>${body}`;
$$('.rail [data-page]').forEach(b=>b.setAttribute('aria-current',(b.dataset.page===state.page||b.dataset.page==='archives'&&state.page==='schema')?'page':'false'));
$('#breadcrumb').textContent=state.page==='archives'?'档案 / '+activeType().label+(state.archiveView==='detail'?' / '+state.title:''):`${names[state.page]} / ${state.page==='browser'?'青禾资料调研':state.page==='versioning'?'调研摘要.md':activeType().label}`;
}
function notice(){const p=state.page,s=state.scenario;let title='',text='',buttons='';if(s==='loading'){title=state.taking&&p==='browser'?'正在撤销智能体控制…':'正在读取…';text=state.taking&&p==='browser'?'正在等待撤销确认。确认前仍不可人工输入，不把取消请求当作已停止。':'已显示的资料会保留，你可以取消本次读取。';buttons=state.taking&&p==='browser'?'':button('取消读取','cancel-load');}if(s==='error'){title='暂时无法读取最新资料';text='上次可用内容仍在。重新读取不会重复提交修改。';buttons=button('重新读取','retry');}if(s==='permission'){title='当前为只读';text='可以查看资料与比较历史。取得写入权限后再继续。';buttons=button('重新检查权限','retry');}if(s==='conflict'){title='请先处理原生笔记中的未保存内容';text='你的表单草稿已保留。本次保存、迁移或覆盖恢复尚未开始。请在原生编辑器保存或解决多个窗口的差异，再回来重试。';buttons=button('查看受影响笔记','affected')+button('重新检查','recheck');}if(s==='recovery'){title=p==='schema'?'迁移中断，等待核验':p==='browser'?'空间已恢复，部分页面尚未打开':'有一项恢复尚未核验完成';text=p==='schema'?'已核验的 2 条关系保留；剩余 1 条等待检查，尚未切换到新格式。':p==='browser'?'已保留原空间和登录资料。不会自动重放网页操作，也不会自动交回智能体。':'保留已完成步骤与原内容，核验后才决定下一步。';buttons=button('核验并继续','resume');}if(s==='unknown'){title='网页操作结果待核实';text='请求已派发，但尚未确认网站是否完成。不要重复提交；先核实网站结果。';buttons=button('核实结果','reconcile');}if(s==='quota'){title='自动历史已暂停：可用空间不足';text='恢复与撤销所需的历史仍被保护。调整配额或处理旧历史后可继续采集；此时覆盖恢复仍需成功创建检查点。';buttons=button('查看保留策略','settings');}if(s==='unsupported'){title='此设备尚不支持受管浏览器';text='当前联合实现仅有 Linux x64 运行时。其他目标桌面平台完成验收前，不启动运行时。';buttons='';}return title?`<section class="notice ${['error','conflict','unknown'].includes(s)?'error':'warning'}" role="${s==='loading'?'status':'alert'}"><h3>${title}</h3><p>${text}</p><div class="actions">${buttons}</div></section>`:'';}
function empty(){return `<section class="empty"><h2>${state.scenario==='noresults'?'没有匹配结果':'这里还没有记录'}</h2><p class="muted">${state.scenario==='noresults'?'调整关键词即可重新查看已有内容。':'创建第一条记录，或导入已有资料。'}</p><div class="actions">${button(state.scenario==='noresults'?'清除搜索':'返回示例内容','reset','primary')}</div></section>`;}
function tabbar(values){return `<nav class="tabs" aria-label="页内内容">${values.map(t=>`<button data-tab="${t}" aria-current="${state.tab===t?'page':'false'}">${t}</button>`).join('')}</nav>`;}
function genericArchiveDetail(){const t=activeType(),r=state.records.find(r=>r.id===state.recordId);return `<div class="detail-back">${button('← 返回'+t.label+'档案','back-to-type','ghost')}</div>`+heading(state.title,typeTitle(t),button('保存草稿','save','primary'),'档案 / '+t.label)+notice()+`<section class="section"><h2>基本资料</h2><div class="fields" style="margin-top:20px"><label>名称<input id="title-input" value="${esc(state.title)}"></label>${t.fields.map(f=>`<label>${esc(f.label)}<input data-value-field="${f.id}" value="${esc(fieldValue(r,f.id)==='—'?'':fieldValue(r,f.id))}" ${f.system?'readonly':''}></label>`).join('')}<label class="wide">正文与记录<textarea id="body-note">${esc(state.draft||r.body)}</textarea></label></div><p class="subtitle">${state.saved?'✓ 草稿已保存到示例内存':'类型列表中隐藏的字段仍保留在档案中。'}</p></section>`;}
function archives(){if(state.archiveView==='list')return archiveList();if(state.activeType!=='project')return genericArchiveDetail();let top=heading(state.title,'项目档案 · 更新于今天 14:32',`<span class="pill good">进行中</span>${button('新建档案','create')}${button('保存草稿','save','primary')}`,'档案 / '+activeType().label);if(['empty','noresults'].includes(state.scenario))return top+notice()+empty();
top=`<div class="detail-back">${button('← 返回'+activeType().label+'档案','back-to-type','ghost')}</div>`+top;let list=mode==='b'?`<section class="section"><div class="section-title"><h2>项目列表</h2><span class="muted">3 条记录 · 选择一行查看</span></div><div class="table-wrap"><table><thead><tr><th>项目名称</th><th>负责人</th><th>阶段</th><th>操作</th></tr></thead><tbody>${['青禾计划','秋季资料整理','山海访谈归档'].map((n,i)=>`<tr><td>${n}</td><td>林夏</td><td>${i?'草稿':'进行中'}</td><td><button data-select="${n}">打开详情</button></td></tr>`).join('')}</tbody></table></div></section>`:'';
let documentLead=mode==='c'?`<p class="document-lead">连接山海工作室与项目团队，整理青禾计划的调研资料、合作关系与历史记录。所有表单共享同一份主资料。</p>`:'';
let content='';if(state.tab==='关系'){content=`<section class="section"><div class="section-title"><h2>关系 · ${state.relation?'3':'2'}</h2>${button('添加关系','relation')}</div>${relationRows()}<p class="subtitle">在任一端编辑，另一端显示同一条关系。</p></section>`;}else if(state.tab==='正文'){content=`<label>原始正文<textarea id="body-note">${esc(state.draft||'本周完成首轮访谈。保留会议记录与附件，下一步核对项目资料。')}</textarea></label><p class="subtitle">自由正文和未识别字段会保留。切换表单不会清空隐藏字段。</p>`;}else if(state.tab==='相关任务'){content=`<h2>首页项目中的执行任务</h2><p class="subtitle">以下是引用，不在档案中建立第二份任务。</p><div class="row"><span class="grow">完成首轮访谈<small>　首页 / 青禾计划</small></span>${button('查看引用','task-reference')}</div><div class="row"><span class="grow">整理调研摘要</span>${button('比较历史','version-link')}</div>`;}else{content=`<section class="section"><div class="section-title"><h2>基本资料</h2><label>表单<select id="form-choice"><option ${state.form==='项目概览'?'selected':''}>项目概览</option><option ${state.form==='交付核对'?'selected':''}>交付核对</option></select></label></div><div class="fields"><label>${esc(state.fieldLabel)}<input id="title-input" value="${esc(state.title)}"></label><label>项目编号<input value="QH-001" readonly aria-describedby="id-hint"><small id="id-hint">编号可含前导零</small></label><label>阶段<select><option>进行中</option><option>草稿</option><option>已归档</option></select></label><label>${state.form==='项目概览'?'启动日期':'交付日期'}<input type="date" value="2026-10-26"></label><label class="wide">项目说明<textarea id="body-note">${esc(state.draft||'整理青禾计划的调研资料与合作关系，形成可追溯的项目档案。')}</textarea></label></div><div class="actions" style="margin-top:16px"><span class="save-state">${state.saved?'✓ 草稿已保存到示例内存':'草稿尚未标记完成'}</span>${button('标记完成','complete','ghost')}</div></section><section class="section"><div class="section-title"><h2>关联资料</h2>${button('添加关系','relation','ghost')}</div>${relationRows()}</section>`;}
if(mode==='c'&&state.tab==='资料'){content=`<article><section class="section"><div class="section-title"><h2>项目说明</h2><span class="save-state">${state.saved?'✓ 已保存':'草稿'}</span></div><label>正文与记录<textarea id="body-note" style="min-height:170px">${esc(state.draft||'整理青禾计划的调研资料与合作关系，形成可追溯的项目档案。')}</textarea></label></section><section class="section"><div class="section-title"><h2>文档中的关联资料</h2>${button('添加关系','relation','ghost')}</div>${relationRows()}</section><section class="section"><div class="section-title"><h2>结构化资料</h2><label>使用表单<select id="form-choice"><option ${state.form==='项目概览'?'selected':''}>项目概览</option><option ${state.form==='交付核对'?'selected':''}>交付核对</option></select></label></div><div class="fields"><label>${esc(state.fieldLabel)}<input id="title-input" value="${esc(state.title)}"></label><label>项目编号<input value="QH-001" readonly></label><label>阶段<select><option>进行中</option><option>草稿</option></select></label><label>${state.form==='项目概览'?'启动日期':'交付日期'}<input type="date" value="2026-10-26"></label></div><div class="actions" style="margin-top:16px">${button('标记完成','complete','ghost')}</div></section></article>`;}
return top+notice()+list+documentLead+tabbar(['资料','关系','正文','相关任务'])+`<div class="columns"><div>${content}</div>${mode==='c'?`<aside class="document-outline"><h3>此档案相关内容</h3>${action('调研资料','browser')}${action('笔记历史','versioning')}${action('类型与表单','schema')}<div class="side-note">主资料、关系、正文各自有清晰入口。</div></aside>`:`<aside class="info"><h3>档案信息</h3><dl><div><dt>档案类型</dt><dd>项目 · 修订 2</dd></div><div><dt>归属</dt><dd>我的知识库</dd></div><div><dt>负责人</dt><dd>林夏</dd></div><div><dt>更新方式</dt><dd>手动保存草稿</dd></div></dl><div class="side-label">继续处理</div>${action('打开调研空间','browser')}${action('查看笔记历史','versioning')}${action('管理类型与表单','schema')}</aside>`}</div>`;}
function relationRows(){return `<div class="relation"><span class="avatar">林</span><span class="grow"><strong>林夏</strong><small>负责人 · 个人档案</small></span><span class="pill">2026.10 起</span>${button('查看','person','ghost')}</div><div class="relation"><span class="avatar">山</span><span class="grow"><strong>山海工作室</strong><small>合作方 · 企业档案</small></span>${button('查看','company','ghost')}</div>${state.relation?'<div class="relation"><span class="avatar">陈</span><span class="grow"><strong>陈舟</strong><small>协作者 · 个人档案</small></span><span class="pill good">已关联</span></div>':''}`;}
function schema(){let top=heading('类型与表单','按自己的资料组织档案，无需新增专用页面。',button('新建类型','new-type','primary'),'档案管理');if(['empty','noresults'].includes(state.scenario))return top+empty();return top+notice()+tabbar(['字段与表单','旧档案迁移'])+(state.tab==='旧档案迁移'?`<section><h2>个人与企业 · 旧格式升级</h2><p class="subtitle">先预检，再核验关系，最后切换。仅查看不会自动升级。</p><div class="steps"><div class="step active">1 预检</div><div class="step ${state.migration>0?'active':''}">2 核验关系</div><div class="step ${state.migration>1?'active':''}">3 切换与回执</div></div><ul class="checks"><li><span class="good">✓</span><div><b>2 份旧档案，3 条关系</b><p class="muted">源文件和稳定身份映射已冻结。</p></div></li><li><span class="good">✓</span><div><b>未发现重复身份</b><p class="muted">缺件与歧义会单独列出，不当作零条处理。</p></div></li><li><span class="${state.migration>1?'good':'warn'}">${state.migration>1?'✓':'○'}</span><div><b>${state.migration>1?'迁移已完成，回执可查看':'等待迁移，旧资料仍有效'}</b><p class="muted">任何一步中断都保留已核验事实。</p></div></li></ul><div class="actions">${button(state.migration>1?'查看回执':'开始迁移',state.migration>1?'receipt':'migrate','primary')}${button('返回字段','schema-fields')}</div></section>`:`<section><div class="section-title"><h2>${state.typeCreated?'项目、个人、企业、'+esc(state.typeName):'项目 · 类型定义'}</h2><span class="pill">修订 2</span></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>类型</th><th>要求</th></tr></thead><tbody><tr><td>${esc(state.fieldLabel)}</td><td>文本</td><td>完成时必填</td></tr><tr><td>项目编号</td><td>标识符</td><td>保留前导零</td></tr><tr><td>启动日期</td><td>日期</td><td>可留空</td></tr></tbody></table></div><div class="section-title"><h2>同一类型，两套表单</h2>${button('编辑字段标签','field-label')}</div><div class="row"><div class="grow"><strong>项目概览</strong><small>名称、编号、启动日期与说明</small></div>${button('使用表单','overview')}</div><div class="row"><div class="grow"><strong>交付核对</strong><small>名称、编号、交付日期与说明</small></div>${button('使用表单','delivery')}</div><p class="subtitle">表单只选择显示哪些字段，共享同一份值。重命名标签不会更换字段身份。</p><div class="panel" style="margin-top:28px"><h3>定义修订</h3><p class="subtitle">发布前预览影响；如果检测到两个设备的不同修订，先解决分叉。</p><div class="actions" style="margin-top:12px">${button('预览发布影响','publish')}${button('演示定义分叉','fork')}</div></div></section>`);}
function versioning(){const managed=state.tab==='档案历史';let top=heading(managed?'青禾计划.md':'调研摘要.md','历史与当前内容比较 · 当前内容固定于 14:32',button('刷新当前内容','refresh')+button('恢复此版本','restore','primary'),'版本管理 / '+(managed?'档案历史':'笔记历史'));if(['empty','noresults'].includes(state.scenario))return top+empty();return top+notice()+`<div class="actions"><label>历史来源<select id="history-source"><option>Git · 今天 10:18 · 首轮访谈</option><option>本地历史 · 今天 13:05</option></select></label><span class="pill">${state.history?'自动历史已开启':'自动历史未开启'}</span>${button('设置','settings','ghost')}</div><div class="section-title" style="margin-top:24px"><h2>比较内容 <small>+ 2 / − 1</small></h2><div class="actions" aria-label="比较布局">${['side','stacked','inline'].map((x,i)=>`<button data-layout="${x}" aria-pressed="${state.layout===x}">${['左右','上下','行内'][i]}</button>`).join('')}</div></div><div class="diff ${state.layout==='side'?'':state.layout}"><article><header>A · 今天 10:18 · Git 提交</header><pre># 青禾调研摘要

访谈目标：了解项目资料管理。
<span class="removed">− 下一步：安排初次访谈。</span>

保留：合作方资料与原始记录。</pre></article><article><header>B · 当前未保存内容 · 14:32</header><pre># 青禾调研摘要

访谈目标：了解项目资料管理。
<span class="added">+ 已完成首轮访谈。</span>
<span class="added">+ 下一步：核对合作方关系。</span>
保留：合作方资料与原始记录。</pre></article></div><div class="notice"><h3>${managed?'档案恢复需要预检':'原笔记仍在原来的编辑器中'}</h3><p>${managed?'只有实体、关系与迁移状态都可安全恢复时，才允许覆盖。否则保留只读比较。':'浏览与取消不会改写笔记。恢复前保留检查点；恢复后自动同步保持暂停，等待你确认。'}</p></div>${state.restored?`<section class="notice"><h3>恢复已完成（示例）</h3><p>检查点和回执已生成；自动同步仍暂停。</p><div class="actions">${button('撤销本次恢复','undo')}${button('查看回执','receipt')}${button('确认恢复同步','sync-resume')}</div></section>`:''}<div class="section"><h2>版本时间线</h2><div class="row"><span class="grow">今天 10:18 · 首轮访谈<small>　Git 提交</small></span><span class="pill">已选中</span></div><div class="row"><span class="grow">昨天 16:40 · 建立调研提纲<small>　Git 提交</small></span>${button('选择比较','older')}</div></div>`;}
function browser(){let top=heading(state.space==='personal'?'个人浏览':'青禾资料调研',state.space==='personal'?'个人空间 · 不接受智能体运行':'任务空间 · 登录状态与其他空间隔离',button('身份与 Cookie','identity')+button('文件与材料','files'),'浏览器');if(['empty','noresults'].includes(state.scenario))return top+empty();return top+notice()+`<section class="notice"><div class="section-title" style="margin:0"><div><h3>${state.space==='personal'?'由你控制':state.control==='human'?'由你控制 · 智能体已停止读取和输入':'智能体控制中 · 你正在只读查看'}</h3><p>${state.space==='personal'?'个人空间始终由你独立操作。':'任务：核对青禾项目的公开介绍。'}</p></div>${state.space==='personal'?'':button(state.control==='human'?'交回智能体':'接管浏览器',state.control==='human'?'return-agent':'takeover',state.control==='human'?'':'primary')}</div></section><div class="browser-toolbar"><span class="pill">1 / 2 标签页</span><div class="address">公开资料 / 青禾计划介绍 · 离线示例</div>${button('重新打开页面','reload-page','ghost')}</div><div class="web-fixture" aria-label="模拟网页"><div class="site-header"><span>山海工作室</span><span class="muted">项目资料</span></div><h2>青禾计划</h2><p>为长期合作建立清晰、可持续的资料记录。以下内容仅为本地交互夹具，不连接真实网站。</p><div class="row" style="margin-top:24px"><span class="grow">项目简介 · 第一版</span>${button('查看资料','web-detail')}</div><div class="row"><span class="grow">访谈纪要 · 公开摘要</span>${button('选为材料','material')}</div></div><div class="row"><span class="grow"><strong>最近操作</strong><small>${state.message||'已打开项目介绍 · 操作完成'}</small></span><span class="pill ${state.scenario==='unknown'?'warn':'good'}">${state.scenario==='unknown'?'待核实':'已确认'}</span></div><p class="subtitle">不因关闭查看页而停止空间；恢复空间不会重放旧网页操作。</p>`;}
function capture(){rememberRecord();if($('#title-input'))state.title=$('#title-input').value;if($('#body-note'))state.draft=$('#body-note').value;}
function render(focus=false){nav();$('#main').innerHTML=({archives,schema,versioning,browser}[state.page])();if(focus){$('#main').focus();say(names[state.page]);}}
function close(){const d=$('#dialog');d.close();if(trigger?.isConnected)trigger.focus();}
function modal(title,body,actions='',kind=''){trigger=document.activeElement;const d=$('#dialog');d.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}<div class="actions">${button('取消','close')}${actions}</div>`;d.dataset.kind=kind;d.showModal();(d.querySelector('input,select,textarea,button')||d).focus();}
function block(){return ['conflict','permission','loading','error','recovery'].includes(state.scenario);}
function guarded(fn){if(block()){modal('本次操作尚未开始',`<p>${state.scenario==='conflict'?'相关原生笔记有未保存内容。你的表单草稿已保留，请先保存或解决差异。':'请先处理页面上显示的问题，再重新检查。'}</p>`);return;}fn();}
function load(){clearTimeout(timer);state.scenario='loading';render();timer=setTimeout(()=>{state.scenario='default';render();say('重新读取完成');},650);}
const handlers={
 navigation(){trigger=document.activeElement;$('#drawer').innerHTML=`<h2>工作台</h2>${Object.entries(names).map(([p,n])=>action(n,p)).join('')}<hr>${$('#sidebar').innerHTML}${button('关闭导航','close-drawer')}`;$('#drawer').showModal();},
 'close-drawer'(){ $('#drawer').close();trigger?.focus();},theme(){document.documentElement.classList.toggle('dark');},close,
 demo(){modal('原型演示控制',`<p>此面板仅用于评审模拟状态，不属于产品界面。所有数据只存在于本页内存，刷新即重置。</p><div class="demo-form"><label>页面<select id="demo-page">${Object.entries(names).map(([p,n])=>`<option value="${p}" ${state.page===p?'selected':''}>${n}</option>`).join('')}</select></label><label>场景<select id="demo-state">${Object.entries(labels).map(([p,n])=>`<option value="${p}" ${state.scenario===p?'selected':''}>${n}</option>`).join('')}</select></label></div>`,button('展示场景','apply-demo','primary'));},
 'apply-demo'(){capture();state.page=$('#demo-page').value;state.scenario=$('#demo-state').value;state.tab=state.page==='schema'?'字段与表单':state.page==='versioning'?'比较':'资料';close();render(true);},reset(){state.scenario='default';state.query='';render();},retry:load,'cancel-load'(){clearTimeout(timer);state.scenario='default';render();say('已取消读取，资料保持不变');},
 recheck(){modal('重新检查原生笔记',`<p>请先在原生编辑器保存或解决差异。原型可以模拟已解决；真实应用必须重新读取所有相关编辑窗口。</p>`,button('模拟已解决并核验','resolved','primary'));},resolved(){state.scenario='default';close();render();say('核验通过，草稿仍在');},affected(){modal('受影响的原生笔记','<p>青禾计划.md · 主窗口有未保存内容。</p><p>原型不打开或保存真实笔记。</p>');},
 save(){capture();guarded(()=>{state.saved=true;render();say('草稿已保存到示例内存');});},complete(){capture();guarded(()=>{if(!state.title.trim()){modal('还需要项目名称','<p>已保留草稿。补充必填项目名称后，再标记完成。</p>');return;}modal('资料检查通过','<p>必填字段完整，可以将档案标记为完成。项目执行阶段保持独立。</p>',button('标记完成','mark-complete','primary'));});},'mark-complete'(){state.saved=true;close();render();say('档案已标记完成');},
 create(){modal('新建'+typeTitle(),'<label>名称<input id="new-name" value="新'+esc(activeType().label)+'"></label><label>创建模板<select><option>空白档案</option><option>标准资料</option></select></label>',button('创建草稿','create-confirm','primary'));},'create-confirm'(){const name=$('#new-name').value.trim();if(!name){$('#new-name').setAttribute('aria-invalid','true');$('#new-name').focus();return;}const id='record-'+(state.records.length+1);state.records.push(seed(id,state.activeType,name));close();chooseRecord(id);},
 relation(){guarded(()=>modal('添加项目关系','<label>关系类型<select><option>协作者</option><option>合作方</option></select></label><label>关联档案<select><option>陈舟 · 个人</option></select></label><label>生效日期<input type="date" value="2026-10-26"></label><p>将在两端显示同一条关系，不复制对方资料。</p>',button('添加关系','relation-confirm','primary')));},'relation-confirm'(){state.relation=true;close();render();say('已关联陈舟');},
 person(){modal('林夏 · 个人档案','<p>与青禾计划的关系：负责人。</p><p>自 2026 年 10 月起生效。反向列表引用同一条关系。</p>');},company(){modal('山海工作室 · 企业档案','<p>与青禾计划的关系：合作方。</p><p>企业主资料仍保存在企业档案中。</p>');},other(){state.title='秋季资料整理';state.draft='';render();},'task-reference'(){modal('首页项目引用','<p>任务：完成首轮访谈。</p><p>任务执行由首页管理；此处只展示关联，不复制任务。</p>');},'version-link'(){navigate('versioning');},
 'new-type'(){modal('新建档案类型','<label>类型名称<input id="new-type-name" value="研究主题"></label><p>从基础字段开始，随后选择字段与表单。个人、企业预设不受影响。</p>',button('创建类型','type-confirm','primary'));}, 'type-confirm'(){const name=$('#new-type-name').value.trim();if(!name)return;const id='custom-'+(state.catalog.length+1);state.catalog.push({id,label:name,fields:[{id:'description',label:'摘要',display:true},...commonFields()]});state.typeCreated=true;state.typeName=name;close();chooseType(id);say('已创建'+name+'类型');},
 'field-label'(){modal('编辑字段显示名称',`<label>显示名称<input id="field-label" value="${esc(state.fieldLabel)}"></label><p>字段身份与存储值保持稳定，隐藏字段也会保留。</p>`,button('保存标签','label-confirm','primary'));},'label-confirm'(){const name=$('#field-label').value.trim();if(!name)return;state.fieldLabel=name;close();render();say('示例标签已保存，字段身份未变化');},overview(){state.form='项目概览';navigate('archives');},delivery(){state.form='交付核对';navigate('archives');},publish(){modal('发布影响预览','<p>2 套表单引用此定义；3 份项目档案继续按原修订读取。发布不会自动改写已有档案。</p>',button('发布新修订','publish-confirm','primary'));},'publish-confirm'(){close();say('新修订已发布到示例内存');},fork(){modal('检测到两个定义修订','<p>两个设备从同一修订分别修改。已阻止相关升级和新建；不会用更新时间覆盖另一个修订。</p><p>请比较分支并由定义管理流程解决。本原型仅展示阻止状态。</p>');},
 'schema-fields'(){state.tab='字段与表单';render();},migrate(){guarded(()=>modal('迁移预检已通过','<p>将迁移 2 份旧档案与 3 条关系。先写入并核验关系，再切换格式；任何中断都保留恢复资料。</p>',button('开始迁移','migrate-confirm','primary')));},'migrate-confirm'(){close();state.migration=1;state.scenario='recovery';render();},resume(){modal('核验后继续','<p>原操作与已完成步骤仍保留。确认剩余步骤可继续后才恢复，不重放已确认的操作。</p>',button('模拟核验成功并继续','resume-confirm','primary'));},'resume-confirm'(){if(state.page==='schema')state.migration=2;if(state.page==='browser')state.control='human';state.scenario='default';close();render();say('核验后恢复完成');},
 settings(){modal('自动本地历史',`<p>由你主动开启。记录普通笔记的当前内容（含未保存内容），排除隐藏与受管敏感内容。</p><label><span><input id="enable-history" type="checkbox" ${state.history?'checked':''}> 开启自动本地历史</span></label><div class="fields"><label>采样间隔（分钟）<input id="policy-interval" type="number" value="${state.policy.interval}" min="1"></label><label>保留时间（天）<input id="policy-days" type="number" value="${state.policy.days}" min="1"></label><label>此库此设备配额（GiB）<input id="policy-quota" type="number" value="${state.policy.quota}" min="1"></label></div><p>切换笔记和重要操作也会采样，相同内容去重。未闭合恢复与可撤销记录始终受保护；配额不足时暂停新采集。</p><p>关闭自动历史仍需要恢复前检查点。</p>`,button('保存设置','settings-confirm','primary'));},'settings-confirm'(){for(const key of ['interval','days','quota']){const input=$('#policy-'+key);if(!input.checkValidity()){input.reportValidity();return;}state.policy[key]=Number(input.value);}state.history=$('#enable-history').checked;close();render();say('历史设置已保存到示例内存');},refresh(){modal('刷新比较中的当前内容','<p>将重新捕获当前内容作为 B 端。原笔记不被保存或覆盖。</p>',button('刷新 B 端','refresh-confirm','primary'));},'refresh-confirm'(){close();say('B 端已显式刷新');},note(){state.tab='比较';render();},'archive-history'(){state.tab='档案历史';render();},older(){modal('昨天 16:40 · 建立调研提纲','<p>此版本只有调研目标，尚无访谈记录。当前内容保持固定。</p>');},
 restore(){guarded(()=>{if(state.tab==='档案历史'){modal('无法安全覆盖此档案','<p>档案预检无法确认历史实体、关系与迁移状态一致。本次恢复被拒绝，可以继续查看与比较。</p>');return;}modal('恢复到当前笔记','<p>对象：调研摘要.md</p><ul class="checks"><li>1. 保存当前内容与磁盘状态为检查点</li><li>2. 再次检查编辑与文件状态</li><li>3. 写入后核验并生成回执</li></ul><p>原批注正文保留。恢复后自动同步暂停，等待你确认。</p>',button('确认恢复','restore-confirm','primary'));});},'restore-confirm'(){state.restored=true;close();render();say('示例恢复完成');},undo(){state.restored=false;render();say('本次恢复已撤销，自动同步仍暂停');},'sync-resume'(){modal('确认恢复自动同步','<p>请先确认恢复结果。继续后按原计划执行同步。</p>',button('确认继续同步','sync-confirm','primary'));},'sync-confirm'(){close();say('已确认恢复自动同步');},receipt(){modal('操作回执 · 示例','<p>已核验完成，原内容与恢复依据保留。回执可用于重启后核对本次结果。</p><p>这里只展示交互，不写入真实档案或 Git。</p>');},
 personal(){state.space='personal';state.control='human';render();},task(){state.space='task';render();},takeover(){if(['unsupported','unknown','permission'].includes(state.scenario))return;state.taking=true;state.scenario='loading';render();setTimeout(()=>{state.taking=false;state.control='human';if(state.page==='browser')state.scenario='default';state.message='已收到撤销确认 · 旧智能体输入与读取已停止';render();say('接管完成');},650);},'return-agent'(){modal('交回智能体','<p>将为当前任务重新授予控制权。旧租约与旧网页操作不会自动复用。</p>',button('交回控制权','agent-confirm','primary'));},'agent-confirm'(){state.control='agent';close();render();},'reload-page':load,
 identity(){modal('导入身份与 Cookie',`<p>目标：${state.space==='personal'?'个人浏览':'青禾资料调研'}。仅在完整验证成功后发布登录资料。</p><label>已授权来源<select><option>本机资料副本 · 示例</option></select></label><label>导入内容<select id="storage-kind"><option value="cookie">Cookie 与身份</option><option value="storage">localStorage / IndexedDB（尚未支持）</option></select></label><p>凭据不可用时拒绝导入，不降级为明文。旧空间失败时保留原资料。</p>`,button('预检导入','import-preflight','primary'));},'import-preflight'(){if($('#storage-kind').value==='storage'){close();modal('此存储类型尚未支持','<p>localStorage 与 IndexedDB 属于后续扩展。本次未导入任何数据，也不会跳过后报告成功。</p>');return;}close();modal('身份预检通过','<p>来源已授权，目标空间匹配。将在临时区验证，再完整读回目标数据。</p>',button('验证并导入','import-confirm','primary'));},'import-confirm'(){state.imported=true;close();modal('身份导入已核验','<p>Cookie 与身份已在目标空间完整读回一致（示例）。其他空间保持隔离。</p>');},files(){modal('文件与材料','<div class="row"><span class="grow">公开摘要.md<small> · 当前任务空间</small></span></div><p>上传、下载与材料授权绑定空间和任务。过期授权不能复用。</p>');},material(){modal('选取资料为材料','<p>公开摘要 · 当前页面与元素。</p><p>仅加入指定会话的未发送输入区，不启动智能体。</p>',button('加入当前任务草稿','material-confirm','primary'));},'material-confirm'(){close();state.message='材料已加入青禾任务未发送输入区（示例）';render();},'web-detail'(){modal('公开项目资料','<p>青禾计划的资料摘要。此内容是本地夹具，没有外部网页请求。</p>');},reconcile(){modal('核实网页结果','<p>请先检查网站是否已经完成原操作。这里模拟读回已完成状态，不再次提交。</p>',button('模拟已完成','reconcile-confirm','primary'));},'reconcile-confirm'(){state.scenario='default';state.message='原操作已确认完成 · 未再次派发';close();render();}
};
for(const name of ['create','new-type','field-label','publish','identity']){const original=handlers[name];handlers[name]=()=>{if(['permission','conflict','unsupported','loading'].includes(state.scenario)){modal('当前无法执行此操作','<p>请先处理页面上显示的权限、未保存内容或平台限制。已有内容保持不变。</p>');return;}original();};}
handlers['back-to-type']=()=>chooseType(state.activeType);
handlers['clear-list']=()=>{const prefs=listPrefs();prefs.query='';prefs.filter='';state.scenario='default';render();};
handlers['display-fields']=()=>{const type=activeType();modal(type.label+' · 显示字段',`<p>勾选要在此类型列表和卡片中显示的字段。名称始终用于识别档案；未勾选的字段值仍保留。</p><fieldset class="field-options"><legend>在列表／卡片中显示</legend>${type.fields.map(f=>`<label><input type="checkbox" data-field-choice="${f.id}" ${f.display?'checked':''}><span>${esc(f.label)}${f.system?'<small>系统字段 · 默认显示</small>':''}</span></label>`).join('')}</fieldset>`,button('保存显示字段','save-display-fields','primary'));};
handlers['save-display-fields']=()=>{const type=activeType();for(const f of type.fields)f.display=!!$(`[data-field-choice="${f.id}"]`)?.checked;close();render();say('列表与卡片显示字段已更新');};
handlers['record-filter']=()=>{const prefs=listPrefs();modal('筛选'+activeType().label+'档案',`<p>筛选决定显示哪些档案，类型设置决定显示哪些字段。</p><label>名称包含<input id="filter-query" value="${esc(prefs.query)}"></label>${state.activeType==='project'?`<label>阶段<select id="filter-stage">${['','进行中','草稿','已完成'].map(x=>`<option value="${x}" ${x===prefs.filter?'selected':''}>${x||'全部阶段'}</option>`).join('')}</select></label>`:''}`,button('应用筛选','apply-record-filter','primary'));};
handlers['apply-record-filter']=()=>{const prefs=listPrefs();prefs.query=$('#filter-query').value;prefs.filter=$('#filter-stage')?.value||'';close();render();};
function navigate(page){capture();clearTimeout(timer);state.page=page;state.scenario='default';state.tab=page==='schema'?'字段与表单':page==='versioning'?'比较':'资料';if($('#drawer').open)$('#drawer').close();render(true);}
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle-type]');if(toggle){const id=toggle.dataset.toggleType;state.expanded.has(id)?state.expanded.delete(id):state.expanded.add(id);nav();return;}const record=e.target.closest('[data-record-row],[data-record-open]');if(record){chooseRecord(record.dataset.recordRow||record.dataset.recordOpen);return;}const type=e.target.closest('[data-type-row]');if(type){chooseType(type.dataset.typeRow);return;}const layout=e.target.closest('[data-list-layout]');if(layout){listPrefs().layout=layout.dataset.listLayout;render();return;}const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action)handlers[b.dataset.action]?.();else if(b.dataset.page)navigate(b.dataset.page);else if(b.dataset.tab){capture();state.tab=b.dataset.tab;render();}else if(b.dataset.layout){state.layout=b.dataset.layout;render();}else if(b.dataset.select){state.title=b.dataset.select;render();}});
document.addEventListener('change',e=>{if(e.target.id==='record-sort'){listPrefs().sort=e.target.value;render();}if(e.target.id==='form-choice'){capture();state.form=e.target.value;render();}if(e.target.id==='history-source'&&e.target.value.startsWith('本地')&&!state.history)modal('尚未开启自动本地历史','<p>主动开启后，新的历史才会采集。已有强制恢复检查点不受该开关影响。</p>',button('打开历史设置','open-settings'));});handlers['open-settings']=()=>{close();handlers.settings();};
document.addEventListener('input',e=>{if(e.target.id==='body-note'){state.draft=e.target.value;state.saved=false;}if(e.target.id==='title-input'){state.title=e.target.value;state.saved=false;}if(e.target.id==='search'){state.treeQuery=e.target.value;const host=$('#archive-tree-host');if(host)host.innerHTML=tree();}if(e.target.id==='record-search'){const start=e.target.selectionStart;listPrefs().query=e.target.value;$('#main').innerHTML=archiveList();const input=$('#record-search');input.focus();input.setSelectionRange(start,start);}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();close();});$('#drawer').addEventListener('cancel',()=>{setTimeout(()=>trigger?.focus(),0);});
document.addEventListener('keydown',e=>{const row=e.target.closest('.archive-tree [role="treeitem"]');if(!row)return;const rows=[...row.closest('[role="tree"]').querySelectorAll('[role="treeitem"]')];const index=rows.indexOf(row);let target=null;if(e.key==='ArrowDown')target=rows[Math.min(rows.length-1,index+1)];if(e.key==='ArrowUp')target=rows[Math.max(0,index-1)];if(e.key==='Home')target=rows[0];if(e.key==='End')target=rows.at(-1);if(target){e.preventDefault();rows.forEach(r=>r.tabIndex=-1);target.tabIndex=0;target.focus();return;}if(e.key==='Enter'||e.key===' '){e.preventDefault();row.dataset.recordRow?chooseRecord(row.dataset.recordRow):chooseType(row.dataset.typeRow);return;}if(e.key==='ArrowRight'&&row.dataset.typeRow){e.preventDefault();const id=row.dataset.typeRow;if(!state.expanded.has(id)){state.expanded.add(id);nav();$(`[data-type-row="${id}"]`).focus();}else row.querySelector('[data-record-row]')?.focus();}if(e.key==='ArrowLeft'){e.preventDefault();const id=row.dataset.typeRow;if(id&&state.expanded.has(id)){state.expanded.delete(id);nav();$(`[data-type-row="${id}"]`).focus();}else row.parentElement.closest('[data-type-row]')?.focus();}});
document.addEventListener('keydown',e=>{if(e.key==='F6'&&!$('#dialog').open&&!$('#drawer').open){e.preventDefault();const groups=[$('.rail'),$('#sidebar'),$('#main')].filter(x=>x.getBoundingClientRect().width&&getComputedStyle(x).display!=='none');const at=groups.findIndex(g=>g.contains(document.activeElement));const g=groups[(at+(e.shiftKey?groups.length-1:1))%groups.length];(g.querySelector('button,input')||g).focus();}});
render();
})();
